    @property
    def a_simple_property(self):
        return "simple"

    @property
    def a_property_with_setter(self):
        return "with_setter"

    @a_property_with_setter.setter
    def a_property_with_setter(self, value):
        pass

    @property
    def a_property_with_deleter(self):
        return "with_deleter"

