    def a_property_with_deleter(self):
        pass

    @property 
    def a_property_with_both(self):
        return "with_both"

    @a_property_with_both.setter
    def a_property_with_both(self, value):
        pass

    @a_property_with_both.deleter
    def a_property_with_both(self):
        pass

    @cached_property
    def a_cached_property(self):
        return "cached"

    @staticmethod
    def a_static_method():
        return "static"

# Test all cases
test_cases = [
    ("Simple property", TestClass.a_simple_property.fget),
    ("Property with setter", TestClass.a_property_with_setter.fget),
    ("Property with deleter", TestClass.a_property_with_deleter.fget),
    ("Property with both", TestClass.a_property_with_both.fget),
